class Agent:
    def __init__(self, name):
        self.name = name
        self.memory = []
    def perceive(self, o):
        self.memory.append(o)
        return o
    def reason(self):
        if not self.memory:
            return 'idle'
        return f'processing: {self.memory[-1]}'
    def act(self):
        d = self.reason()
        self.memory.append(d)
        return d

