        if i not in s.tasks:return None
        t=s.tasks[i];t['progress']=p
        if p>=100:t['state']='completed'
        elif t['state']=='created'and p>0:t['state']='in_progress'
        return t
    def status(s,i):return s.tasks.get(i)

