class AITutor:
    def __init__(s):s.prof={};s.kn={}
    def update(s,uid,topic,score):
        if uid not in s.prof:s.prof[uid]={}
        s.prof[uid][topic]=score
    def recommend(s,uid):
        w=s.weak(uid)
        if w:return f'建议复习: {w[0]}'
        return '全部优秀！继续探索新知识！'
    def weak(s,uid):
        p=s.prof.get(uid,{})
        w=[t for t,sc in p.items()if sc<60]
        return sorted(w,key=lambda t:p[t])
